import{c as r,a1 as s,V as d,j as c,g as t,n as o,o as l,m as n,a7 as m}from"./chunks/framework.BQhatpAZ.js";const k=JSON.parse('{"title":"Specification","description":"Guided tour of the TOON specification – sections, conformance checklists, media type, and versioning.","frontmatter":{"description":"Guided tour of the TOON specification – sections, conformance checklists, media type, and versioning."},"headers":[],"relativePath":"en/reference/spec.md","filePath":"reference/spec.md","lastUpdated":1783377783000}'),p={name:"en/reference/spec.md"};function h(a,e,u,f,g,b){const i=s("CopyOrDownloadAsMarkdownButtons");return d(),c("div",null,[e[1]||(e[1]=t("div",{style:{display:"none"},hidden:"true","aria-hidden":"true"},"Are you an LLM? You can read better optimized documentation at /en/reference/spec.md for this page in Markdown format",-1)),e[2]||(e[2]=t("h1",{id:"specification",tabindex:"-1"},[o("Specification "),t("a",{class:"header-anchor",href:"#specification","aria-label":'Permalink to "Specification"'},"​")],-1)),l(i),e[3]||(e[3]=n('<p>The <a href="https://github.com/toon-format/spec" target="_blank" rel="noreferrer">TOON specification</a> is the authoritative reference for implementing encoders, decoders, and validators. It defines the concrete syntax, normative encoding/decoding behavior, and strict-mode validation rules.</p><p>You don&#39;t need this page to <em>use</em> TOON. It&#39;s mainly for implementers and contributors. If you&#39;re looking to learn how to use TOON, start with the <a href="/guide/getting-started.html">Getting Started</a> guide instead.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>The TOON specification is stable, but also an idea in progress. Nothing&#39;s set in stone – help shape where it goes by contributing to it or sharing feedback.</p></div><h2 id="current-version" tabindex="-1">Current Version <a class="header-anchor" href="#current-version" aria-label="Permalink to &quot;Current Version&quot;">​</a></h2>',4)),t("p",null,[t("strong",null,"Spec v"+m(a.$spec.version),1),e[0]||(e[0]=o(' (2026-05-20) is the current published Working Draft. It is stable for implementation but not yet finalized; see "Status of This Document" in the spec for details.',-1))]),e[4]||(e[4]=n('<h2 id="media-type-file-extension" tabindex="-1">Media Type &amp; File Extension <a class="header-anchor" href="#media-type-file-extension" aria-label="Permalink to &quot;Media Type &amp; File Extension&quot;">​</a></h2><p>The spec defines a provisional media type and file extension in <a href="https://github.com/toon-format/spec/blob/main/SPEC.md#17-iana-considerations" target="_blank" rel="noreferrer">§17</a>:</p><ul><li><strong>Media type:</strong> <code>text/toon</code> (provisional, not yet IANA‑registered; UTF‑8 only)</li><li><strong>File extension:</strong> <code>.toon</code></li></ul><p>TOON documents are always UTF‑8 with LF (<code>\\n</code>) line endings; the optional <code>charset</code> parameter, when present, is <code>utf-8</code>.</p><h2 id="guided-tour-of-the-spec" tabindex="-1">Guided Tour of the Spec <a class="header-anchor" href="#guided-tour-of-the-spec" aria-label="Permalink to &quot;Guided Tour of the Spec&quot;">​</a></h2><h3 id="core-concepts" tabindex="-1">Core Concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to &quot;Core Concepts&quot;">​</a></h3><p><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#1-terminology-and-conventions" target="_blank" rel="noreferrer">§1 Terminology and Conventions</a>: Defines key terms like &quot;indentation level&quot;, &quot;active delimiter&quot;, &quot;strict mode&quot;, and RFC2119 keywords (MUST, SHOULD, MAY).</p><p><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#2-data-model" target="_blank" rel="noreferrer">§2 Data Model</a>: Specifies the JSON data model (objects, arrays, primitives), array/object ordering requirements, and canonical number formatting (canonical decimal for values in <code>[1e-6, 1e21)</code> or zero; exponent form permitted outside).</p><p><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#3-encoding-normalization-reference-encoder" target="_blank" rel="noreferrer">§3 Encoding Normalization</a>: Defines how non-JSON types (Date, BigInt, NaN, Infinity, undefined, etc.) are normalized before encoding. Required reading for encoder implementers.</p><p><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#4-decoding-interpretation-reference-decoder" target="_blank" rel="noreferrer">§4 Decoding Interpretation</a>: Specifies how decoders map text tokens to host values (quoted strings, unquoted primitives, numeric parsing with leading-zero handling). Decoders default to strict mode (<code>strict = true</code>) in the reference implementation; strict-mode errors are enumerated in §14.</p><h3 id="syntax-rules" tabindex="-1">Syntax Rules <a class="header-anchor" href="#syntax-rules" aria-label="Permalink to &quot;Syntax Rules&quot;">​</a></h3><p><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#5-concrete-syntax-and-root-form" target="_blank" rel="noreferrer">§5 Concrete Syntax and Root Form</a>: Defines TOON&#39;s line-oriented, indentation-based notation and how to determine whether the root is an object, array, or primitive.</p><p><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#6-header-syntax-normative" target="_blank" rel="noreferrer">§6 Header Syntax</a>: Normative ABNF grammar for array headers: <code>key[N&lt;delim?&gt;]{fields}:</code>. Specifies bracket segments, delimiter symbols, and field lists.</p><p><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#7-strings-and-keys" target="_blank" rel="noreferrer">§7 Strings and Keys</a>: Complete quoting rules (when strings MUST be quoted), escape sequences (only <code>\\\\</code>, <code>\\&quot;</code>, <code>\\n</code>, <code>\\r</code>, <code>\\t</code>, and <code>\\uXXXX</code> for other U+0000–U+001F controls are valid), and key encoding requirements.</p><p><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#8-objects" target="_blank" rel="noreferrer">§8 Objects</a>: Object field encoding (key: value), nesting rules, key order preservation, and empty object handling.</p><p><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#9-arrays" target="_blank" rel="noreferrer">§9 Arrays</a>: Covers all array forms: primitive (inline), arrays of objects (tabular), mixed/non-uniform (list), and arrays of arrays. Includes tabular detection requirements.</p><p><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#10-objects-as-list-items" target="_blank" rel="noreferrer">§10 Objects as List Items</a>: Indentation rules for objects appearing in list items (first field on the hyphen line), including the canonical pattern when the first field is a tabular array (header on the hyphen line, rows at depth +2, sibling fields at depth +1).</p><p><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#11-delimiters" target="_blank" rel="noreferrer">§11 Delimiters</a>: Delimiter scoping (document vs active), delimiter-aware quoting, and parsing rules for comma/tab/pipe delimiters.</p><p><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#12-indentation-and-whitespace" target="_blank" rel="noreferrer">§12 Indentation and Whitespace</a>: Encoding requirements (consistent spaces, no tabs in indentation, no trailing spaces/newlines) and decoding rules (strict vs non-strict indentation handling).</p><h3 id="conformance-and-validation" tabindex="-1">Conformance and Validation <a class="header-anchor" href="#conformance-and-validation" aria-label="Permalink to &quot;Conformance and Validation&quot;">​</a></h3><p><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#13-conformance-and-options" target="_blank" rel="noreferrer">§13 Conformance and Options</a>: Defines conformance classes (encoder, decoder, validator), standardized options, and conformance checklists.</p><p><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#134-key-folding-and-path-expansion" target="_blank" rel="noreferrer">§13.4 Key Folding and Path Expansion</a>: Optional encoder feature (key folding) and decoder feature (path expansion) for collapsing/expanding dotted paths, with deep-merge semantics and strict/non-strict conflict resolution.</p><p><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#14-strict-mode-errors-and-diagnostics-authoritative-checklist" target="_blank" rel="noreferrer">§14 Strict Mode Errors and Diagnostics</a>: <strong>Authoritative checklist</strong> of all strict-mode errors: array count and width mismatches (§14.1), syntax and structural errors (§14.2), path expansion conflicts (§14.3), and duplicate sibling keys (§14.4).</p><h3 id="implementation-guidance" tabindex="-1">Implementation Guidance <a class="header-anchor" href="#implementation-guidance" aria-label="Permalink to &quot;Implementation Guidance&quot;">​</a></h3><p><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#15-security-considerations" target="_blank" rel="noreferrer">§15 Security Considerations</a>: Injection risks, quoting rules, and strict-mode checks relevant to security.</p><p><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#16-internationalization" target="_blank" rel="noreferrer">§16 Internationalization</a>: Unicode handling and locale-independent number formatting.</p><p><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#17-iana-considerations" target="_blank" rel="noreferrer">§17 IANA Considerations</a>: Media type registration plans and provisional status.</p><p><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#18-versioning-and-extensibility" target="_blank" rel="noreferrer">§18 Versioning and Extensibility</a>: How the spec evolves: major vs minor bumps and the extensibility policy.</p><p><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#19-intellectual-property-considerations" target="_blank" rel="noreferrer">§19 Intellectual Property Considerations</a>: Licensing and IP terms for the specification.</p><p><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#appendix-f-host-type-normalization-examples-informative" target="_blank" rel="noreferrer">Appendix F: Host Type Normalization Examples</a>: Non-normative guidance for Go, JavaScript, Python, Rust, and Java implementations on normalizing language-specific types.</p><p><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#appendix-c-test-suite-and-compliance-informative" target="_blank" rel="noreferrer">Appendix C: Test Suite and Compliance</a>: Reference test suite at <a href="https://github.com/toon-format/spec/tree/main/tests" target="_blank" rel="noreferrer">github.com/toon-format/spec/tree/main/tests</a> for validating implementations.</p><h2 id="spec-sections-at-a-glance" tabindex="-1">Spec Sections at a Glance <a class="header-anchor" href="#spec-sections-at-a-glance" aria-label="Permalink to &quot;Spec Sections at a Glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Section</th><th>Topic</th><th>When to Read</th></tr></thead><tbody><tr><td>§1–4</td><td>Data model, normalization, decoding</td><td>Implementing encoders/decoders</td></tr><tr><td>§5–6</td><td>Syntax, headers, root form</td><td>Implementing parsers</td></tr><tr><td>§7</td><td>Strings, keys, quoting, escaping</td><td>Implementing string handling</td></tr><tr><td>§8–10</td><td>Objects, arrays, list items</td><td>Implementing structure encoding</td></tr><tr><td>§11–12</td><td>Delimiters, indentation, whitespace</td><td>Implementing formatting and validation</td></tr><tr><td>§13</td><td>Conformance, options, key folding/path expansion</td><td>Implementing options and features</td></tr><tr><td>§14</td><td>Strict-mode errors</td><td>Implementing validators</td></tr><tr><td>§15–16</td><td>Security, internationalization</td><td>Operational considerations</td></tr><tr><td>§17–19</td><td>IANA, versioning, IP</td><td>Ecosystem and licensing</td></tr></tbody></table><h2 id="conformance-checklists" tabindex="-1">Conformance Checklists <a class="header-anchor" href="#conformance-checklists" aria-label="Permalink to &quot;Conformance Checklists&quot;">​</a></h2><p>The spec includes three conformance checklists:</p><h3 id="encoder-checklist-§13-1-↗-spec-md" tabindex="-1">Encoder Checklist (§13.1) <sup><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#131-encoder-conformance-checklist" target="_blank" rel="noreferrer">↗ SPEC.md</a></sup> <a class="header-anchor" href="#encoder-checklist-§13-1-↗-spec-md" aria-label="Permalink to &quot;Encoder Checklist (§13.1) &lt;sup&gt;[↗ SPEC.md](https://github.com/toon-format/spec/blob/main/SPEC.md#131-encoder-conformance-checklist)&lt;/sup&gt;&quot;">​</a></h3><p>Key requirements:</p><ul><li>Produce UTF-8 with LF line endings</li><li>Use consistent indentation (default 2 spaces, no tabs)</li><li>Escape <code>\\\\</code>, <code>\\&quot;</code>, <code>\\n</code>, <code>\\r</code>, <code>\\t</code> in quoted strings, and use <code>\\uXXXX</code> for any other U+0000–U+001F control character; lone surrogates are rejected</li><li>Quote strings with active delimiter, colon, or structural characters</li><li>Emit array lengths <code>[N]</code> matching actual count</li><li>Preserve object key order</li><li>Emit numbers per §2 (canonical decimal in <code>[1e-6, 1e21)</code> or zero; exponent form permitted outside)</li><li>Convert <code>-0</code> to <code>0</code>, <code>NaN</code>/±Infinity to <code>null</code></li><li>Emit booleans and null as lowercase literals (<code>true</code>, <code>false</code>, <code>null</code>)</li><li>No trailing spaces or trailing newline</li><li>When <code>keyFolding=&quot;safe&quot;</code> is enabled, folding MUST follow §13.4: <ul><li>Only fold IdentifierSegment keys (letters/digits/underscores, no dots),</li><li>Do not introduce collisions with existing sibling keys,</li><li>Do not fold segments that would require quoting.</li></ul></li><li>When <code>flattenDepth</code> is set, folding MUST stop at the configured number of segments (§13.4).</li></ul><h3 id="decoder-checklist-§13-2-↗-spec-md" tabindex="-1">Decoder Checklist (§13.2) <sup><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#132-decoder-conformance-checklist" target="_blank" rel="noreferrer">↗ SPEC.md</a></sup> <a class="header-anchor" href="#decoder-checklist-§13-2-↗-spec-md" aria-label="Permalink to &quot;Decoder Checklist (§13.2) &lt;sup&gt;[↗ SPEC.md](https://github.com/toon-format/spec/blob/main/SPEC.md#132-decoder-conformance-checklist)&lt;/sup&gt;&quot;">​</a></h3><p>Key requirements:</p><ul><li>Parse array headers per §6 (length, delimiter, fields)</li><li>Split inline arrays and tabular rows using active delimiter only</li><li>Unescape quoted strings with only valid escapes</li><li>Type unquoted primitives: true/false/null → booleans/null, numeric → number, else → string</li><li>Enforce strict-mode rules when <code>strict=true</code></li><li>Preserve array order and object key order</li><li>When <code>expandPaths=&quot;safe&quot;</code> is enabled, expand dotted keys into nested objects per §13.4: <ul><li>Split on <code>.</code>, only expand when all segments are IdentifierSegments,</li><li>Deep-merge overlapping paths (object + object),</li><li>Do not perform element-wise array merges.</li></ul></li><li>With <code>expandPaths=&quot;safe&quot;</code> and <code>strict=true</code> (default), MUST error on any expansion conflict (§14.3).</li><li>With <code>expandPaths=&quot;safe&quot;</code> and <code>strict=false</code>, MUST apply deterministic last-write-wins (LWW) conflict resolution (§13.4).</li></ul><h3 id="validator-checklist-§13-3-↗-spec-md" tabindex="-1">Validator Checklist (§13.3) <sup><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#133-validator-conformance-checklist" target="_blank" rel="noreferrer">↗ SPEC.md</a></sup> <a class="header-anchor" href="#validator-checklist-§13-3-↗-spec-md" aria-label="Permalink to &quot;Validator Checklist (§13.3) &lt;sup&gt;[↗ SPEC.md](https://github.com/toon-format/spec/blob/main/SPEC.md#133-validator-conformance-checklist)&lt;/sup&gt;&quot;">​</a></h3><p>Validators should verify:</p><ul><li>Structural conformance (headers, indentation, list markers)</li><li>Whitespace invariants (no trailing spaces/newlines)</li><li>Delimiter consistency between headers and rows</li><li>Array length counts match declared <code>[N]</code></li><li>All strict-mode requirements (including path-expansion conflicts when enabled)</li></ul><h2 id="versioning" tabindex="-1">Versioning <a class="header-anchor" href="#versioning" aria-label="Permalink to &quot;Versioning&quot;">​</a></h2><p>The spec uses semantic versioning (major.minor):</p><ul><li><strong>Major version</strong> (e.g., v2 → v3): Breaking changes, incompatible with previous versions</li><li><strong>Minor version</strong> (e.g., v3.1 → v3.2): Clarifications, additional requirements, or backward-compatible additions</li></ul><p>See <a href="https://github.com/toon-format/spec/blob/main/SPEC.md#appendix-d-document-changelog-informative" target="_blank" rel="noreferrer">Appendix D: Document Changelog</a> for detailed version history.</p><h2 id="contributing-to-the-spec" tabindex="-1">Contributing to the Spec <a class="header-anchor" href="#contributing-to-the-spec" aria-label="Permalink to &quot;Contributing to the Spec&quot;">​</a></h2><p>The spec is community-maintained at <a href="https://github.com/toon-format/spec" target="_blank" rel="noreferrer">github.com/toon-format/spec</a>. We welcome contributions of all kinds: reporting ambiguities or errors, proposing clarifications and examples, adding test cases to the reference suite, or discussing edge cases and normative behavior. Your feedback helps shape the format.</p>',50))])}const S=r(p,[["render",h]]);export{k as __pageData,S as default};
